package publicstatus

import (
	"fmt"
	"html/template"
)

func uptimePercent(successes, total int64) string {
	return fmt.Sprintf("%.2f%%", float64(successes)*100/float64(total))
}

var statusTemplate = template.Must(template.New("status").Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="30"><meta name="description" content="Live public service health reported by Vigil."><title>Service status · Vigil</title><link rel="icon" href="https://vigil.boniluan.com/assets/favicon.svg?v=20260922b" type="image/svg+xml">
<style>
:root{color-scheme:dark;--bg:#07100e;--surface:#0d1916;--surface2:#11221d;--line:#213a32;--strong:#315144;--text:#f0f6f3;--muted:#94aaa2;--green:#50e3a4;--green-soft:#8aefc1;--down:#fb7185;--pending:#fbbf24;font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:radial-gradient(circle at 80% -5%,rgba(80,227,164,.12),transparent 30%),var(--bg);color:var(--text)}body:before{content:"";position:fixed;inset:0;pointer-events:none;background:linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);background-size:52px 52px;mask-image:linear-gradient(#000,transparent 75%)}a{color:var(--green);text-decoration:none}a:hover{color:var(--green-soft)}a:focus-visible{outline:2px solid var(--green);outline-offset:4px}header{position:relative;z-index:2;max-width:1380px;min-height:76px;margin:auto;padding:0 28px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(148,170,162,.15)}.brand{display:flex;align-items:center;gap:10px;color:var(--text);font-size:19px;font-weight:850}.mark{position:relative;width:21px;height:21px;border:2px solid var(--green);border-radius:50%;box-shadow:inset 0 0 0 4px var(--bg),0 0 18px rgba(80,227,164,.18)}.mark:after{content:"";position:absolute;inset:5px;border-radius:50%;background:var(--green)}.header-links{display:flex;gap:20px;align-items:center;font-size:13px}.header-links a:first-child{color:var(--muted)}.operator-link{padding:8px 13px;border:1px solid var(--line);border-radius:999px}main{position:relative;z-index:1;max-width:1380px;margin:auto;padding:76px 28px 90px}.hero{display:grid;grid-template-columns:1fr auto;gap:50px;align-items:end;margin-bottom:40px}.eyebrow{margin:0 0 12px;color:var(--green);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.eyebrow:before{content:"";display:inline-block;width:22px;height:1px;margin:0 8px 4px 0;background:var(--green)}h1{margin:0;font-size:clamp(48px,6vw,76px);line-height:1;letter-spacing:-.06em}h1 em{color:var(--green-soft);font-style:normal}.lead{max-width:680px;margin:22px 0 0;color:#adc0b9;font-size:17px}.updated{padding:12px 15px;border:1px solid var(--line);border-radius:12px;background:rgba(17,34,29,.7);color:var(--muted);font-size:11px}.updated strong{display:block;color:var(--text);font-size:13px}.summary{display:grid;grid-template-columns:1.5fr repeat(2,minmax(150px,.5fr));gap:14px;margin:0 0 34px}.summary-card,.banner{position:relative;overflow:hidden;padding:22px;border:1px solid var(--line);border-radius:17px;background:linear-gradient(145deg,rgba(17,34,29,.94),rgba(9,20,16,.84));box-shadow:0 18px 50px rgba(0,0,0,.14)}.summary-card span{display:block;color:var(--muted);font-size:11px}.summary-card strong{display:block;margin-top:6px;font-size:32px;letter-spacing:-.04em}.banner{display:flex;align-items:center;gap:15px}.banner-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;font-weight:900}.banner.good{border-color:#327e59}.banner.good .banner-icon{background:#103c2d;color:var(--green)}.banner.attention{border-color:#806035}.banner.attention .banner-icon{background:#3e3212;color:var(--pending)}.banner strong,.banner span{display:block}.banner span{color:var(--muted);font-size:12px}.pulse{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px rgba(80,227,164,.08);animation:pulse 2.4s ease-in-out infinite}.service-heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:48px 0 17px}.service-heading h2{margin:0;font-size:24px;letter-spacing:-.025em}.service-heading p{margin:0;color:var(--muted);font-size:12px}.service-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.service{position:relative;padding:21px;border:1px solid var(--line);border-radius:17px;background:linear-gradient(145deg,rgba(17,34,29,.9),rgba(9,20,16,.8));transition:transform .2s ease,border-color .2s ease}.service:hover{transform:translateY(-3px);border-color:var(--strong)}.service-top{display:grid;grid-template-columns:42px 1fr auto;gap:13px;align-items:center}.service-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;background:#103c2d;color:var(--green);font-weight:850}.service h3{margin:0;font-size:16px}.service p{margin:3px 0 0;color:var(--muted);font-size:10px}.state{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:999px;font-size:9px;font-weight:850;letter-spacing:.08em;text-transform:uppercase}.state:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.state-up{background:#103c2d;color:var(--green)}.state-down{background:#461c27;color:var(--down)}.state-pending{background:#3e3212;color:var(--pending)}.state-paused{background:#28362f;color:#bdc9c3}.uptime{display:flex;justify-content:space-between;align-items:end;margin-top:20px;padding-top:16px;border-top:1px solid var(--line)}.uptime span{color:var(--muted);font-size:10px}.uptime strong{font-size:20px;letter-spacing:-.03em}.uptime-line{height:3px;margin-top:12px;border-radius:5px;background:linear-gradient(90deg,var(--green),rgba(80,227,164,.14))}.empty{padding:34px;border:1px dashed var(--strong);border-radius:17px;text-align:center;color:var(--muted);background:rgba(17,34,29,.5)}.note{max-width:820px;margin:30px 0 0;color:var(--muted);font-size:12px}footer{position:relative;z-index:1;max-width:1380px;margin:auto;padding:30px 28px;display:flex;justify-content:space-between;gap:24px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}@keyframes pulse{0%,100%{box-shadow:0 0 0 4px rgba(80,227,164,.08)}50%{box-shadow:0 0 0 9px rgba(80,227,164,0)}}@media(max-width:820px){.hero{grid-template-columns:1fr}.updated{justify-self:start}.summary{grid-template-columns:1fr 1fr}.banner{grid-column:1/-1}.service-grid{grid-template-columns:1fr}}@media(max-width:560px){header{padding:12px 17px}.header-links>a:first-child{display:none}main{padding:54px 17px 72px}h1{font-size:48px}.summary{grid-template-columns:1fr}.banner{grid-column:auto}.service-top{grid-template-columns:38px 1fr}.service-icon{width:38px;height:38px}.state{grid-column:2;justify-self:start}.service-heading{align-items:flex-start;flex-direction:column}.service-heading p{display:none}footer{padding:25px 17px;flex-direction:column}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.pulse{animation:none}.service{transition:none}}
</style></head><body>
<header><a class="brand" href="https://status.boniluan.com/"><span class="mark" aria-hidden="true"></span>Vigil Status</a><div class="header-links"><a href="https://vigil.boniluan.com/">About Vigil</a><a class="operator-link" href="https://vigil.boniluan.com/monitors">Operator login ↗</a></div></header>
<main><section class="hero"><div><p class="eyebrow">Live service health</p><h1>Everything at<br><em>a glance.</em></h1><p class="lead">A deliberately limited public view of services monitored by Vigil. Private targets, diagnostics, and operational data remain protected.</p></div><div class="updated"><span class="pulse"></span>Auto-refreshing every 30 seconds<strong>Updated {{.Updated}}</strong></div></section>
{{if .Services}}<section class="summary" aria-label="Status summary">{{if .AllOperational}}<div class="banner good"><div class="banner-icon">✓</div><div><strong>All listed services operational</strong><span>No current availability failures detected.</span></div></div>{{else}}<div class="banner attention"><div class="banner-icon">!</div><div><strong>Some services need attention</strong><span>See individual states below.</span></div></div>{{end}}<article class="summary-card"><span>Public services</span><strong>{{.Total}}</strong></article><article class="summary-card"><span>Operational</span><strong>{{.Operational}}</strong></article></section>
<div class="service-heading"><div><p class="eyebrow">Current state</p><h2>Monitored services</h2></div><p>Health and uptime update automatically.</p></div><section class="service-grid" aria-label="Public services">{{range .Services}}<article class="service"><div class="service-top"><div class="service-icon">{{printf "%.1s" .Name}}</div><div><h3>{{.Name}}</h3><p>Last checked {{.LastChecked}}</p></div><span class="state state-{{.State}}">{{.State}}</span></div><div class="uptime"><span>Successful checks · 24 hours</span><strong>{{.Uptime}}</strong></div><div class="uptime-line" aria-hidden="true"></div></article>{{end}}</section>{{else}}<div class="empty">No public services are listed yet.</div>{{end}}
<p class="note">Uptime is successful completed checks divided by all completed checks in the last 24 hours. Pending and paused periods are not counted as failures. Vigil reports observed checks, not a guarantee of continuous availability.</p></main><footer><span>Powered by Vigil · Self-hosted monitoring</span><span>Incidents and maintenance notices are planned for v0.2.</span></footer></body></html>`))
